package productui

func workflowStartStylesheet() string {
	return `.workflow-start-page{display:grid;gap:var(--hcm-space-4);max-inline-size:72rem;margin-inline:auto}.workflow-start-header{display:flex;justify-content:space-between;gap:var(--hcm-space-3);align-items:start}.workflow-start-title h1{margin-block:var(--hcm-space-1)}.workflow-start-title p{max-inline-size:62ch;margin:0}.workflow-start-search{display:grid;gap:var(--hcm-space-1);max-inline-size:42rem}.workflow-start-search input{inline-size:100%;box-sizing:border-box;min-block-size:var(--hcm-control-height);padding-inline:var(--hcm-space-2);font:inherit;color:var(--ink);background:var(--surface);border:1px solid var(--control-border);border-radius:var(--hcm-radius-control)}.workflow-start-count{margin:0;color:var(--muted);font-size:var(--hcm-font-size-small)}.workflow-start-results{display:grid;gap:var(--hcm-space-4)}.workflow-start-section{display:grid;gap:var(--hcm-space-2)}.workflow-start-section h2{margin:0;font-size:var(--hcm-font-size-heading)}.workflow-start-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(16rem,1fr));gap:var(--hcm-space-2)}.workflow-start-card{display:grid;gap:var(--hcm-space-2);min-inline-size:0;padding:var(--hcm-space-3);border:1px solid var(--line);border-radius:var(--hcm-radius-surface);background:var(--surface);box-shadow:var(--hcm-shadow-resting)}.workflow-start-card.active{outline:2px solid var(--accent);outline-offset:2px}.workflow-start-card-head{display:flex;align-items:center;justify-content:space-between;gap:var(--hcm-space-2)}.workflow-start-card-icon{display:grid;place-items:center;inline-size:2rem;block-size:2rem;color:var(--accent);background:var(--soft);border-radius:var(--hcm-radius-control)}.workflow-start-card-icon svg{inline-size:1.2rem;block-size:1.2rem}.workflow-start-favorite{display:grid;place-items:center;inline-size:2rem;block-size:2rem;padding:0;border:0;background:transparent;color:var(--accent);cursor:pointer}.workflow-start-favorite-icon{inline-size:1.2rem;block-size:1.2rem}.workflow-start-card h3{margin:0;overflow-wrap:anywhere}.workflow-start-card p{margin:0;min-block-size:2.7em}.workflow-start-card-meta{display:flex;align-items:center;min-block-size:1.4rem}.workflow-start-availability,.workflow-start-unavailable{font-size:var(--hcm-font-size-small);font-weight:600;color:var(--muted)}.workflow-start-unavailable[data-availability=missing_authority],.workflow-start-unavailable[data-availability=no_capability],.workflow-start-unavailable[data-availability=missing_prerequisite],.workflow-start-unavailable[data-availability=quarantined]{color:var(--warning)}.workflow-start-open{justify-self:start}.workflow-start-state{display:grid;gap:var(--hcm-space-2);padding:var(--hcm-space-4)}.workflow-start-state h2,.workflow-start-state p{margin:0}.workflow-start-state .workflow-start-card{margin-block-start:var(--hcm-space-2);max-inline-size:28rem}@media (max-width:640px){.workflow-start-header{display:block}.workflow-start-grid{grid-template-columns:1fr}.workflow-start-card{padding:var(--hcm-space-2)}}@media (prefers-reduced-motion:reduce){.workflow-start-card{transition:none}}`
}
